import {printedArtwork} from '../../modeling/artwork.js';
const front=new URL('./official-front.png',import.meta.url).href,back=new URL('./official-back.png',import.meta.url).href,mode=new URL('./official-mode.png',import.meta.url).href;
export function addStickers(host){const target=host.parts['QRCode complete native assembled shell'];return{front:printedArtwork(host,{target,url:front,size:[21.134,15],position:[0,14.5,8],face:'front',depth:.2,name:'QRCode front exact-product original raster',artworkKind:'official-raster'}),back:printedArtwork(host,{target,url:back,size:[19.652,26.009],position:[0,7.6,-8],face:'back',depth:.2,name:'QRCode rear exact-product original raster',artworkKind:'official-raster'}),mode:printedArtwork(host,{target,url:mode,size:[4.682,3],position:[-12,4.5,-3.45],face:'left',depth:.5,name:'QRCode side UART I2C original raster',artworkKind:'official-raster'})};}
